/* A separate complete Vedic report, built from the selected native's existing calculations.
 * The supplied PDF is a layout reference only; none of its personal data or publisher text is copied.
 */
(function(root){'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),language=()=>root.KPPreferences?.get?.().language||'english',pick=(en,mr)=>language()==='marathi'?mr:en;
const MR={'vedic-information':'जन्म तपशील व जन्मकालीन पंचांग','vedic-rashi':'जन्म कुंडली व ग्रहस्थिती','vedic-cusps':'भाव स्पष्ट · विद्यमान केपी भाव','vedic-vargas':'षोडशवर्ग कुंडल्या','vedic-shadbala':'षड्बल','vedic-bhava-bala':'भावबल','vedic-vimshopaka':'विंशोपक बल','vedic-vaisheshika':'वैशेषिकांश बल','vedic-ashtakavarga':'भिन्न अष्टकवर्ग','vedic-sarva':'सर्वाष्टकवर्ग व सर्वतोभद्र चक्र','vedic-shodhana':'अष्टकवर्ग शोधन','vedic-prastara':'प्रस्तार अष्टकवर्ग','vedic-ashtaka-summary':'अष्टकवर्ग सारांश','vedic-aspects':'वैदिक ग्रहदृष्टी','vedic-maitri':'ग्रह मैत्री','vedic-dasha-bhukti':'विंशोत्तरी महादशा व अंतर्दशा','vedic-current-bhukti':'सध्याची भुक्ती व अंतर','vedic-current-antara':'सध्याचे अंतर व सूक्ष्म','vedic-current-sukshma':'सध्याचे सूक्ष्म व प्राण','vedic-ishta':'इष्ट व कष्ट फल','vedic-nakshatra':'जन्म नक्षत्र फल','vedic-pada':'जन्म नक्षत्र चरण फल','vedic-planets':'जन्म कुंडलीचे वैदिक फल','vedic-house-results':'बारा भावेशांचे वैदिक फल','vedic-dasha-results':'दशा फल','vedic-remedies':'पारंपरिक उपाय','vedic-manglik':'मंगळ दोष परीक्षण','vedic-sade-sati':'शनी साडेसाती','vedic-varshaphal':'वर्षफल'};
function title(){return pick('Complete Vedic Report','संपूर्ण वैदिक अहवाल');}
function facts(data){
 const n=data.native,date=new Date(Date.parse(n.date)+Number(n.location.timezone||0)*3600000),civil=date.toISOString().slice(0,19).replace('T',' '),d1=data.vargas[1],sign=id=>esc((language()==='marathi'?['मेष','वृषभ','मिथुन','कर्क','सिंह','कन्या','तूळ','वृश्चिक','धनु','मकर','कुंभ','मीन']:['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces'])[d1.find(p=>p.id===id).sign]),panchang=root.KPNatalPanchangPredictions?.rows(data,language())||[],coordinate=(value,longitude)=>root.KPClientPresentation?.formatCoordinate?.(Number(value),longitude)||String(value??'');
 const factorNames={nakshatra:['Birth nakshatra','जन्म नक्षत्र'],yoga:['Birth yoga','जन्म योग'],weekday:['Birth weekday','जन्म वार'],tithi:['Birth tithi','जन्म तिथी'],karana:['Birth karana','जन्म करण']},pairs=[[pick('Name','नाव'),esc(n.name)],[pick('Birth date and time','जन्म दिनांक व वेळ'),esc(civil)],[pick('Birthplace','जन्म स्थळ'),esc(n.location.place)],[pick('Latitude','अक्षांश'),esc(coordinate(n.location.latitude,false))],[pick('Longitude','रेखांश'),esc(coordinate(n.location.longitude,true))],[pick('UTC offset','वेळेचा फरक'),esc(n.location.timezone)],[pick('Ascendant','लग्न'),sign('As')],[pick('Moon sign','चंद्रराशी'),sign('Mo')]];
 const extra=root.KPBasicInformation?.facts?.(),lookup=new Map(extra?.ready?extra.groups.flat():[]),labels={'Chart type':'कुंडली प्रकार','Gender':'लिंग','Ayanamsha':'अयनांश','Local mean time':'स्थानिक मध्यम वेळ','Sidereal time':'नाक्षत्र वेळ','Sunrise':'सूर्योदय','Sunset':'सूर्यास्त','Gana':'गण','Nadi':'नाडी','Yoni':'योनी','Varna':'वर्ण','Vashya':'वश्य','Birth Dasha':'जन्म महादशा','Remaining birth Dasha':'महादशेचा भोग्यकाळ','Birth Bhukti':'जन्म भुक्ती','Remaining birth Bhukti':'भुक्तीचा भोग्यकाळ'},values={Deva:'देव',Manushya:'मनुष्य',Rakshasa:'राक्षस',Adi:'आद्य',Madhya:'मध्य',Antya:'अंत्य',Horse:'घोडा',Elephant:'हत्ती',Sheep:'मेंढी',Serpent:'सर्प',Dog:'कुत्रा',Cat:'मांजर',Rat:'उंदीर',Cow:'गाय',Buffalo:'म्हैस',Tiger:'वाघ',Deer:'हरिण',Monkey:'वानर',Mongoose:'मुंगूस',Lion:'सिंह',Shudra:'शूद्र',Vaishya:'वैश्य',Kshatriya:'क्षत्रिय',Brahmin:'ब्राह्मण',Quadruped:'चतुष्पाद',Human:'मानव',Water:'जल',Forest:'वनचर',Insect:'कीटक'},group=(heading,keys)=>'<section><h3>'+heading+'</h3><dl>'+keys.filter(k=>lookup.has(k)).map(k=>{const raw=String(lookup.get(k)),value=language()==='marathi'?(values[raw]||root.KPLanguage?.translate(raw)||raw):raw;return '<div><dt>'+pick(k,labels[k])+'</dt><dd>'+esc(value)+'</dd></div>';}).join('')+'</dl></section>';
 return '<div class="vc-facts"><section><h3>'+pick('Birth details','जन्म तपशील')+'</h3><dl>'+pairs.map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+v+'</dd></div>').join('')+'</dl></section><section><h3>'+pick('Birth Panchang','जन्मकालीन पंचांग')+'</h3><dl>'+panchang.map(r=>'<div><dt>'+pick(...factorNames[r.natalFactor])+'</dt><dd>'+esc(r.title)+'</dd></div>').join('')+'</dl><p>'+pick('Birth-time sidereal positions and the native’s recorded time zone are used.','जन्मवेळेची निरयन ग्रहस्थिती व नोंदविलेला वेळक्षेत्र वापरले आहे.')+'</p></section></div>'+(lookup.size?'<div class="vc-facts vc-more-facts">'+group(pick('Calculation details','जन्म गणनेचे तपशील'),['Chart type','Gender','Ayanamsha','Local mean time','Sidereal time','Sunrise','Sunset'])+group(pick('Traditional birth references','पारंपरिक जन्म संदर्भ'),['Gana','Nadi','Yoni','Varna','Vashya','Birth Dasha','Remaining birth Dasha','Birth Bhukti','Remaining birth Bhukti'])+'</div>':'');
}
function sudarshan(data){
 const rows=data.vargas[1],bases=['As','Mo','Su'],glyphs=language()==='marathi'?{As:'ल',Su:'र',Mo:'चं',Ma:'मं',Me:'बु',Ju:'गु',Ve:'शु',Sa:'श',Ra:'रा',Ke:'के'}:{},polar=(r,a)=>[180+r*Math.cos(a),180+r*Math.sin(a)],parts=['<svg class="vc-sudarshan" viewBox="0 0 360 360" role="img" aria-label="'+pick('Sudarshan chakra: Ascendant, Moon and Sun references','सुदर्शन चक्र: लग्न, चंद्र व रवी संदर्भ')+'">'];
 for(const r of [42,85,127,170])parts.push('<circle cx="180" cy="180" r="'+r+'"/>');
 for(let i=0;i<12;i++){const a=(i*30-105)*Math.PI/180,[x1,y1]=polar(42,a),[x2,y2]=polar(170,a);parts.push('<path d="M'+x1+' '+y1+'L'+x2+' '+y2+'"/>');}
 for(const [ring,id] of bases.entries())for(let i=0;i<12;i++){
  const base=rows.find(p=>p.id===id).sign,sign=(base+i)%12,r=[149,106,63][ring],a=(i*30-90)*Math.PI/180,[x,y]=polar(r,a),occupants=rows.filter(p=>p.sign===sign).map(p=>glyphs[p.id]||p.id),font=Math.max(4,8-occupants.length*.5);
  parts.push('<text x="'+x+'" y="'+(y-4)+'">'+(sign+1)+'</text><text x="'+x+'" y="'+(y+6)+'" style="font-size:'+font+'px">'+esc(occupants.join(' '))+'</text>');
 }
 parts.push('<text class="vc-om" x="180" y="187">ॐ</text></svg>');
 return parts.join('')+'<p class="vc-caption">'+pick('Outer ring: Ascendant · Middle ring: Moon · Inner ring: Sun. Numbers denote Rashi signs; abbreviations denote the natal planets.','बाह्य वर्तुळ: लग्न · मध्य वर्तुळ: चंद्र · अंतर्गत वर्तुळ: रवी. अंक राशी दर्शवितात; संक्षिप्त नावे जन्मग्रह दर्शवितात.')+'</p>';
}
function vargaTable(data){const divs=root.KPVedicMath.DIVISIONS,ids=['As',...root.KPVedicMath.IDS,'Ra','Ke'];return '<div class="v-table-wrap"><table class="v-table"><thead><tr><th>'+pick('Division','वर्ग')+'</th>'+ids.map(id=>'<th>'+esc(id)+'</th>').join('')+'</tr></thead><tbody>'+divs.map(d=>'<tr><th>D'+d+'</th>'+ids.map(id=>'<td>'+(data.vargas[d]?.find(p=>p.id===id)?.sign+1||'—')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p>'+pick('Cells show the Rashi number (1–12) in each division.','प्रत्येक वर्गातील राशीचा क्रमांक (१–१२) दाखविला आहे.')+'</p>';}
function prose(rows){return rows.length?rows.map(r=>'<article class="vc-prediction" data-no-localize><h3>'+esc(r.title||'')+'</h3><p>'+esc(r.text)+'</p></article>').join(''):'<p>'+pick('No supplied interpretation is available in the selected language.','निवडलेल्या भाषेत दिलेला फलविचार उपलब्ध नाही.')+'</p>';}
function gemstoneReference(data){
 const rows=data.vargas[1],asc=rows.find(p=>p.id==='As').sign,stones={Su:['Ruby','माणिक'],Mo:['Pearl','मोती'],Ma:['Red coral','पोवळे'],Me:['Emerald','पाचू'],Ju:['Yellow sapphire','पुष्कराज'],Ve:['Diamond','हिरा'],Sa:['Blue sapphire','नीलम']};
 return '<p>'+pick('Traditional Vedic gemstone reference using the existing 1st, 5th and 11th house sign-lord convention.','विद्यमान प्रथम, पंचम व एकादश भावांच्या राशीस्वामींची पारंपरिक वैदिक रत्न पद्धत.')+'</p><table class="v-table"><thead><tr><th>'+pick('House','भाव')+'</th><th>'+pick('Sign lord','राशीस्वामी')+'</th><th>'+pick('Gemstone','रत्न')+'</th></tr></thead><tbody>'+[1,5,11].map(h=>{const id=root.KPVedicMath.LORDS[(asc+h-1)%12];return '<tr><td>'+h+'</td><td>'+root.KPVedicSymbols.planet(rows.find(p=>p.id===id),rows)+'</td><td>'+pick(...stones[id])+'</td></tr>';}).join('')+'</tbody></table>';
}
function sections(data){
 if(!data?.ready)return [];
 const out=[],add=(id,heading,html)=>out.push({id,title:heading,html});
 const predictions=root.KPVedicPredictions?.match(data).rows||[];
 for(const [id,en] of root.KPVedicUI.definitions){
  let blocks;
  if(id==='vedic-information')blocks=[facts(data)];
  else if(id==='vedic-planets')blocks=[prose(predictions.filter(r=>['ascendant','planet-house'].includes(r.kind)))];
  else if(id==='vedic-house-results')blocks=[prose(root.KPVedicBhav?.rows(data,language())||[])];
  else blocks=root.KPVedicUI.contents(id,data);
  for(const [i,html] of blocks.entries())add(id,pick(en,MR[id]||en)+(blocks.length>1?' · '+(i+1)+'/'+blocks.length:''),html);
  if(id==='vedic-remedies'&&(!root.KPCustomerFeatures||root.KPCustomerFeatures.allowed('gemstones')))add('vedic-gemstone-reference',pick('Vedic gemstone references','वैदिक रत्न मार्गदर्शन'),gemstoneReference(data));
  if(id==='vedic-rashi'){
   const moon=data.vargas[1].find(p=>p.id==='Mo');
   const moonRows=data.vargas[1].map(p=>({...p,id:p.id==='As'?'NatalAsc':p.id}));moonRows.unshift({...moon,id:'As'});
   add('vedic-moon-navamsa',pick('Moon reference and Navamsa','चंद्र संदर्भ कुंडली व नवमांश'),'<div class="vc-chart-pair">'+root.KPVedicUI.chart(moonRows,pick('Moon reference','चंद्र संदर्भ'))+root.KPVedicUI.chart(data.vargas[9],pick('D9 · Navamsa','डी९ · नवमांश'))+'</div>');
   add('vedic-sudarshan',pick('Sudarshan Chakra','सुदर्शन चक्र'),sudarshan(data));
   add('vedic-varga-table',pick('Shodashavarga table','षोडशवर्ग सारणी'),vargaTable(data));
   add('vedic-natal-references',pick('Birth Panchang and Kalsarpa references','जन्म पंचांग व कालसर्प संदर्भ'),prose(predictions.filter(r=>['kalsarpa','natal-panchang'].includes(r.kind))));
  }
 }
 return out;
}
function pages(data){const all=sections(data);return all.map((s,i)=>{const page=document.createElement('section');page.className='report-page v-report-page v-complete-report-page';page.dataset.reportSection=s.id;page.dataset.vedicComplete='true';page.innerHTML='<header class="vc-header" data-no-localize><span>'+esc(data.native.name)+'</span><b aria-hidden="true">ॐ</b><span>'+title()+'</span></header><h2 class="vc-heading" data-no-localize>'+esc(s.title)+'</h2><main class="v-report-content">'+s.html+'</main><footer class="vc-footer" data-no-localize><span>KP MASTER</span><span>'+pick('Section','विभाग')+' '+(i+1)+' / '+all.length+'</span></footer>';return page;});}
const css=`.v-complete-report-page .vc-header{position:static!important;top:auto!important;width:auto!important;display:flex!important;align-items:center;justify-content:space-between;gap:8px;border-bottom:1px solid #aa665b;color:#843c35;padding:2mm 0;font-size:11px}.vc-header b{font-size:26px}.vc-heading{text-align:center;color:#843c35;border-bottom:1px solid #c28e78;padding:2mm 0;margin:2mm 0 4mm;font-size:16px}.vc-facts{display:grid;grid-template-columns:1fr 1fr;gap:6mm}.vc-more-facts{margin-top:4mm}.vc-facts section{border:1px solid #c28e78;border-radius:4mm;padding:3mm}.vc-facts dl{margin:0}.vc-facts dl>div{display:grid;grid-template-columns:1fr 1.2fr;gap:2mm;border-bottom:1px solid #ead9ce;padding:1.5mm 0}.vc-facts dt{font-weight:600}.vc-facts dd{margin:0}.vc-chart-pair{display:grid;grid-template-columns:1fr 1fr;gap:4mm}.vc-prediction{break-inside:avoid;border-bottom:1px solid #dac4b4;padding:2mm 0}.vc-prediction p{white-space:pre-line;line-height:1.5}.vc-prediction h3:empty{display:none}.vc-footer{display:flex;justify-content:space-between;font-size:8px;color:#7a5348;border-top:1px solid #ba9781;margin-top:4mm;padding-top:2mm}.vc-sudarshan{display:block;width:170mm;max-width:100%;height:auto;margin:auto;fill:none;stroke:#9a7463;stroke-width:.5}.vc-sudarshan text{fill:#18334d;stroke:none;font:8px Arial,'Nirmala UI',sans-serif;text-anchor:middle}.vc-sudarshan .vc-om{font-size:24px;fill:#843c35}.vc-caption{text-align:center;font-size:10px}.report-page.report-page.v-complete-report-page{border:1px solid #ab6a5b!important;border-radius:4mm!important;background:#fffef7!important}.v-complete-report-page .v-table th{background:#f4e5d8!important;color:#62392e}.v-complete-report-page .v-table td{background:#fffef7!important}.v-complete-report-page .v-chart{background:#fffef0!important}.v-complete-report-page .v-symbol-legend{break-inside:avoid}@media print{.report-page.report-page.v-complete-report-page{border:0!important;border-radius:0!important}.vc-header{break-after:avoid}.vc-chart-pair,.vc-sudarshan{break-inside:avoid}body.vc-preview>.kp-print-page-frame{border-color:#ab6a5b!important}}`;
function decorate(doc){doc.body.classList.add('vc-preview');const style=doc.createElement('style');style.textContent=css;doc.head.append(style);}
root.KPCompleteVedicReport=Object.freeze({title,sections,pages,decorate,css});if(typeof module!=='undefined'&&module.exports)module.exports=root.KPCompleteVedicReport;
})(typeof window==='undefined'?globalThis:window);
